package com.example.grafanapocket;

import android.app.*;import android.os.*;import android.widget.*;import org.json.*;import java.util.*;import java.net.URLEncoder;

public class PanelSelectionActivity extends Activity {
    Connection connection;LinearLayout choices;TextView status;final List<CheckBox> checks=new ArrayList<>();
    @Override public void onCreate(Bundle b){super.onCreate(b);connection=new SecureStore(this).get(getIntent().getStringExtra("id"));LinearLayout root=Ui.column(this);Ui.fill(root,Ui.title(this,"选择要显示的数据窗口"));status=Ui.title(this,"正在读取 Dashboard…");status.setTextSize(14);Ui.fill(root,status);choices=new LinearLayout(this);choices.setOrientation(LinearLayout.VERTICAL);Ui.fill(root,choices);Button save=Ui.button(this,"保存选择（不选择则显示完整面板）");save.setOnClickListener(v->save());Ui.fill(root,save);ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);new Thread(this::load).start();}
    void load(){try{String uid=GrafanaApi.uid(connection.dashboard);if(uid.isEmpty())throw new Exception("Dashboard 路径中没有 UID，请使用 /d/UID/名称");JSONObject response=new JSONObject(GrafanaApi.get(connection,"/api/dashboards/uid/"+URLEncoder.encode(uid,"UTF-8")));JSONArray panels=response.getJSONObject("dashboard").optJSONArray("panels");List<JSONObject> all=new ArrayList<>();collect(panels,all);Set<String> selected=new HashSet<>(Arrays.asList(connection.panels.split(",")));runOnUiThread(()->{status.setText("共找到 "+all.size()+" 个窗口，可多选：");for(JSONObject p:all){int id=p.optInt("id",-1);if(id<0)continue;CheckBox box=new CheckBox(this);box.setText(p.optString("title","未命名窗口")+"  ·  ID "+id+"  ·  "+p.optString("type"));box.setTextColor(android.graphics.Color.WHITE);box.setTag(String.valueOf(id));box.setChecked(selected.contains(String.valueOf(id)));checks.add(box);Ui.fill(choices,box);}});}catch(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}}
    static void collect(JSONArray a,List<JSONObject> out){if(a==null)return;for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p==null)continue;if(!"row".equals(p.optString("type")))out.add(p);collect(p.optJSONArray("panels"),out);}}
    void save(){StringBuilder s=new StringBuilder();for(CheckBox c:checks)if(c.isChecked()){if(s.length()>0)s.append(',');s.append(c.getTag());}connection.panels=s.toString();new SecureStore(this).save(connection);setResult(RESULT_OK);finish();}
}
